-- Read-only audit: a source-specific owner cancellation is neither a missing projection nor a payment.
DO $patch$
DECLARE target regprocedure:='public.lts_recurring_future_gap_audit_v6(uuid,date,date)'::regprocedure;
 definition text;attributes jsonb;part jsonb;restored text;
 patches jsonb:=$pairs$[{"name": "source-specific-owner-cancellations", "old": "), fixed_specs AS (", "new": "), owner_cancelled_v360 AS MATERIALIZED (\n SELECT DISTINCT r.id,r.replacement_ref source_ref,r.date_from event_date,\n public.lts_forecast_series_key_v1(r.description_exact) series_key,'expense'::text direction\n FROM public.lts_projection_replacement_rule r JOIN public.evento_base b\n ON b.usuario_id=r.user_id AND r.replacement_ref='evento_base:'||b.idx\n WHERE r.user_id=p_user_id AND r.active IS TRUE AND r.action='suppress_legacy'\n AND r.replacement_source='owner_confirmation' AND r.source_table='evento_base'\n AND r.evidence->>'scope'='one_original_occurrence' AND r.evidence->>'legacy_ref'=r.replacement_ref\n AND r.date_from=r.date_to AND b.dados->>'dia'=r.date_from::text\n AND b.dados->>'desc'=r.description_exact AND b.dados->>'conta'=r.account_exact\n AND b.dados->>'efeito'='saida'\n AND CASE WHEN coalesce(b.dados->>'valor','')~'^[0-9]+([.][0-9]+)?$' THEN (b.dados->>'valor')::numeric>0 ELSE false END\n AND (SELECT count(*) FROM public.evento_base other WHERE other.usuario_id=b.usuario_id AND other.idx=b.idx)=1\n), fixed_specs AS (", "count": 1}, {"name": "period-exception-records", "old": " SELECT p.*,\n (SELECT count(*) FROM future", "new": " SELECT p.*,\n (SELECT count(*) FROM owner_cancelled_v360 x WHERE p.cadence='monthly' AND x.series_key=p.series_key AND x.direction=p.direction\n AND x.event_date BETWEEN p.period_start AND p.period_end)::int cancelled_count,\n (SELECT coalesce(jsonb_agg(jsonb_build_object('date',x.event_date,'rule_id',x.id,'source_ref',x.source_ref,'status','cancelled_by_owner') ORDER BY x.event_date,x.id),'[]'::jsonb)\n FROM owner_cancelled_v360 x WHERE p.cadence='monthly' AND x.series_key=p.series_key AND x.direction=p.direction\n AND x.event_date BETWEEN p.period_start AND p.period_end) confirmed_exceptions,\n (SELECT count(*) FROM future", "count": 1}, {"name": "gap-is-not-cancelled-occurrence", "old": "c.future_count+c.actual_count=0 AND c.unconfirmed_count=0", "new": "c.future_count+c.actual_count=0 AND c.unconfirmed_count=0 AND c.cancelled_count=0", "count": 3}, {"name": "separate-cancelled-from-paid-status", "old": " jsonb_agg(jsonb_build_object('period_start',c.period_start,'period_end',c.period_end,'actual_events',c.actual_count,'future_events',c.future_count,'unconfirmed_obligations',c.unconfirmed_count,'unconfirmed_evidence',c.unconfirmed_evidence,'status',CASE WHEN c.future_count+c.actual_count>0 THEN 'covered' WHEN c.unconfirmed_count>0 THEN 'awaiting_payment_evidence' ELSE 'review' END) ORDER BY c.period_start) period_coverage,", "new": " jsonb_agg((jsonb_build_object('period_start',c.period_start,'period_end',c.period_end,'actual_events',c.actual_count,'future_events',c.future_count,'unconfirmed_obligations',c.unconfirmed_count,'unconfirmed_evidence',c.unconfirmed_evidence,'status',CASE WHEN c.future_count+c.actual_count>0 THEN 'covered' WHEN c.unconfirmed_count>0 THEN 'awaiting_payment_evidence' WHEN c.cancelled_count>0 THEN 'cancelled_by_owner' ELSE 'review' END)||CASE WHEN c.cancelled_count>0 THEN jsonb_build_object('confirmed_exceptions',c.confirmed_exceptions) ELSE '{}'::jsonb END) ORDER BY c.period_start) period_coverage,", "count": 1}, {"name": "series-exception-evidence", "old": " (SELECT max(f.event_date) FROM future f WHERE f.series_key=c.series_key AND f.direction=c.direction) last_future_date,", "new": " (SELECT coalesce(jsonb_agg(jsonb_build_object('date',x.event_date,'rule_id',x.id,'source_ref',x.source_ref,'status','cancelled_by_owner') ORDER BY x.event_date,x.id),'[]'::jsonb)\n FROM owner_cancelled_v360 x CROSS JOIN params p WHERE c.cadence='monthly' AND x.series_key=c.series_key AND x.direction=c.direction\n AND x.event_date BETWEEN date_trunc('month',p.as_of)::date AND p.horizon_end) owner_confirmed_exceptions,\n (SELECT max(f.event_date) FROM future f WHERE f.series_key=c.series_key AND f.direction=c.direction) last_future_date,", "count": 1}, {"name": "do-not-ask-confirmed-cancellation-again", "old": " END) item,c.gaps\n FROM checks c", "new": " END)||CASE WHEN jsonb_array_length(c.owner_confirmed_exceptions)>0 THEN jsonb_build_object('owner_confirmed_exceptions',c.owner_confirmed_exceptions,\n 'review_reason','As ocorrências listadas como canceladas já foram confirmadas. Revise apenas os demais períodos sem cobertura; não crie novo pagamento para as ocorrências canceladas.') ELSE '{}'::jsonb END item,c.gaps\n FROM checks c", "count": 1}]$pairs$::jsonb;
BEGIN
 SELECT pg_get_functiondef(target),to_jsonb(p)-'prosrc' INTO definition,attributes FROM pg_proc p WHERE p.oid=target;
 IF strpos(definition,'owner_cancelled_v360')>0 THEN
  restored:=definition;
  FOR part IN SELECT value FROM jsonb_array_elements(patches) WITH ORDINALITY p(value,n) ORDER BY n DESC LOOP
   restored:=replace(restored,part->>'new',part->>'old');
  END LOOP;
  IF md5(restored)<>'481697f51a8d2b8a4bb59d6b1c758a1b' THEN RAISE EXCEPTION 'V360_REPLAY_SOURCE_CHANGED';END IF;
  RETURN;
 END IF;
 IF md5(definition)<>'481697f51a8d2b8a4bb59d6b1c758a1b' THEN RAISE EXCEPTION 'V360_AUDIT_SOURCE_CHANGED';END IF;
 FOR part IN SELECT value FROM jsonb_array_elements(patches) LOOP
  IF (length(definition)-length(replace(definition,part->>'old','')))/length(part->>'old')<>(part->>'count')::int
  THEN RAISE EXCEPTION 'V360_AUDIT_ANCHOR_CHANGED: %',part->>'name';END IF;
  definition:=replace(definition,part->>'old',part->>'new');
 END LOOP;
 EXECUTE definition;
 IF attributes IS DISTINCT FROM(SELECT to_jsonb(p)-'prosrc' FROM pg_proc p WHERE p.oid=target)
 THEN RAISE EXCEPTION 'V360_AUDIT_ATTRIBUTES_CHANGED';END IF;
END $patch$;
